// Simple reflex game: catch falling stars
const canvas = document.getElementById('game');
if (!canvas) throw new Error('Canvas with id "game" not found');
const ctx = canvas.getContext('2d');
canvas.width = canvas.width || 400;
canvas.height = canvas.height || 600;

// Player settings
const player = {
  x: canvas.width / 2,
  y: canvas.height - 30,
  radius: 20,
  speed: 5,
  dx: 0,
};

// Star settings
const stars = [];
const starRadius = 10;
const spawnInterval = 1000; // ms
let lastSpawn = 0;
let score = 0;
let gameOver = false;

// Input handling
const keys = { ArrowLeft: false, ArrowRight: false };
window.addEventListener('keydown', (e) => {
  if (e.key in keys) keys[e.key] = true;
});
window.addEventListener('keyup', (e) => {
  if (e.key in keys) keys[e.key] = false;
});

function updatePlayer() {
  if (keys.ArrowLeft) player.dx = -player.speed;
  else if (keys.ArrowRight) player.dx = player.speed;
  else player.dx = 0;
  player.x += player.dx;
  // keep inside canvas
  if (player.x - player.radius < 0) player.x = player.radius;
  if (player.x + player.radius > canvas.width) player.x = canvas.width - player.radius;
}

function spawnStar(timestamp) {
  if (timestamp - lastSpawn > spawnInterval) {
    const x = Math.random() * (canvas.width - 2 * starRadius) + starRadius;
    stars.push({ x, y: -starRadius, radius: starRadius, speed: 2 + Math.random() * 2 });
    lastSpawn = timestamp;
  }
}

function updateStars() {
  for (let i = stars.length - 1; i >= 0; i--) {
    const s = stars[i];
    s.y += s.speed;
    // collision with player
    const dx = s.x - player.x;
    const dy = s.y - player.y;
    const dist = Math.hypot(dx, dy);
    if (dist < s.radius + player.radius) {
      stars.splice(i, 1);
      score++;
      continue;
    }
    // missed star => game over
    if (s.y - s.radius > canvas.height) {
      gameOver = true;
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // player
  ctx.fillStyle = 'steelblue';
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fill();
  // stars
  ctx.fillStyle = 'gold';
  for (const s of stars) {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
    ctx.fill();
  }
  // score
  ctx.fillStyle = 'black';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${score}`, 10, 20);
}

function loop(timestamp) {
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'white';
    ctx.font = '24px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2 - 60, canvas.height / 2);
    ctx.fillText(`Final Score: ${score}`, canvas.width / 2 - 80, canvas.height / 2 + 30);
    return;
  }
  updatePlayer();
  spawnStar(timestamp);
  updateStars();
  draw();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
